    break;

  case GKYL_SUM:
    for (long k = 0; k < nc; ++k) {
      out[k] = 0;
    }
    for (size_t i = 0; i < arr->size; ++i) {
      const double *d = gkyl_array_cfetch(arr, i);
      for (long k = 0; k < nc; ++k) {
        out[k] += d[k];
      }
    }
    break;
  default:
    assert(false);
    break;
  }
