static int get_basis_type(const char *nm)
{
  if (strcmp(nm, "ms") == 0) {
    return GKYL_BASIS_MODAL_SERENDIPITY;
  } else if (strcmp(nm, "mt") == 0) {
    return GKYL_BASIS_MODAL_TENSOR;
  }
  return -1;
}

static int get_mp_recon_type(const char *nm)
{
  if (strcmp(nm, "u1") == 0) {
    return GKYL_MP_U1;
  } else if (strcmp(nm, "u3") == 0) {
    return GKYL_MP_U3;
  } else if (strcmp(nm, "u5") == 0) {
    return GKYL_MP_U5;
  } else if (strcmp(nm, "c2") == 0) {
    return GKYL_MP_C2;
  } else if (strcmp(nm, "c4") == 0) {
    return GKYL_MP_C4;
  } else if (strcmp(nm, "c6") == 0) {
    return GKYL_MP_C6;
  }

  return -1;
}

static struct gkyl_app_args parse_app_args(int argc, char **argv)
